const body = $json.body ?? {};

const reviewRequestId = String(body.review_request_id ?? '').trim();
const applicationId = String(body.application_id ?? '').trim();
const action = String(body.action ?? '').trim().toLowerCase();

const allowedActions = [
  'approve',
  'edit',
  'reject',
  'regenerate',
];

if (!reviewRequestId) {
  throw new Error('review_request_id is required.');
}

if (!applicationId) {
  throw new Error('application_id is required.');
}

if (!allowedActions.includes(action)) {
  throw new Error(
    `Invalid review action: ${action || '<blank>'}.`
  );
}

const expectedProposals = Array.isArray(body.expected_proposals)
  ? body.expected_proposals.map(proposal => ({
      proposal_id: String(proposal.proposal_id ?? '').trim(),
      proposed_text: String(proposal.proposed_text ?? ''),
    }))
  : [];

if (expectedProposals.length === 0) {
  throw new Error(
    'expected_proposals must contain at least one proposal.'
  );
}

if (
  expectedProposals.some(
    proposal =>
      !proposal.proposal_id ||
      !proposal.proposed_text
  )
) {
  throw new Error(
    'Each expected proposal must contain proposal_id and proposed_text.'
  );
}

const expectedProposalIds =
  expectedProposals.map(
    proposal => proposal.proposal_id
  );

const edits = Array.isArray(body.edits)
  ? body.edits
  : [];

if (action === 'edit' && edits.length === 0) {
  throw new Error(
    'An edit review must contain at least one edited proposal.'
  );
}

return {
  json: {
    review_request_id: reviewRequestId,
    application_id: applicationId,
    action,
    expected_proposals: expectedProposals,
    expected_proposal_ids: expectedProposalIds,
    edits,
    reviewer_comment:
      body.reviewer_comment == null
        ? null
        : String(body.reviewer_comment).trim() || null,

    review_idempotency_key:
      `careerops-review-${reviewRequestId}`,
  },
};

const request = $('Validate Review Request').item.json;

const analysis =
  $('Get Current Analysis').item.json.structuredContent.analysis;

const expectedIds =
  [...request.expected_proposal_ids].sort();

const currentIds =
  [...analysis.reviewable_proposal_ids].sort();

if (analysis.status === 'awaiting_review') {
  if (!analysis.allowed_review_actions.includes(request.action)) {
    throw new Error(
      `Review action '${request.action}' is not currently allowed.`
    );
  }

  if (
    JSON.stringify(expectedIds) !==
    JSON.stringify(currentIds)
  ) {
    throw new Error(
      'The review request is stale: current reviewable proposals have changed.'
    );
  }

  const currentProposals =
    analysis.cv_proposals
      .filter(proposal =>
        currentIds.includes(proposal.proposal_id)
      )
      .map(proposal => ({
        proposal_id: proposal.proposal_id,
        proposed_text: proposal.proposed_text,
      }))
      .sort((a, b) =>
        a.proposal_id.localeCompare(b.proposal_id)
      );

  const expectedProposals =
    request.expected_proposals
      .map(proposal => ({
        proposal_id: proposal.proposal_id,
        proposed_text: proposal.proposed_text,
      }))
      .sort((a, b) =>
        a.proposal_id.localeCompare(b.proposal_id)
      );

  if (
    JSON.stringify(expectedProposals) !==
    JSON.stringify(currentProposals)
  ) {
    throw new Error(
      'The review request is stale: proposal content has changed.'
    );
  }
} else if (analysis.status !== 'completed') {
  throw new Error(
    `Unsupported analysis status: ${analysis.status}`
  );
}

const currentProposals =
  analysis.cv_proposals.filter(
    proposal =>
      request.expected_proposal_ids.includes(
        proposal.proposal_id
      )
  );

return {
  json: {
    ...request,
    analysis_status: analysis.status,
    current_reviewable_proposals: currentProposals,
    current_reviewable_proposal_ids:
      request.expected_proposal_ids,
  },
};

const review =
  $('Validate Current Review State').item.json;

const proposalIds = review.expected_proposal_ids;

let edits = [];

if (review.action === 'edit') {
  edits = review.edits.map(edit => ({
    proposal_id: String(edit.proposal_id ?? '').trim(),
    edited_text: String(edit.edited_text ?? '').trim(),
  }));

  const editIds = edits
    .map(edit => edit.proposal_id)
    .sort();

  const expectedIds = [...proposalIds].sort();

  if (
    JSON.stringify(editIds) !==
    JSON.stringify(expectedIds)
  ) {
    throw new Error(
      'An edit decision must provide replacement text for every proposal under review.'
    );
  }

  if (
    edits.some(
      edit =>
        !edit.proposal_id ||
        !edit.edited_text
    )
  ) {
    throw new Error(
      'Edited proposal IDs and replacement text must not be blank.'
    );
  }
}

const approvedProposalIds =
  review.action === 'approve'
    ? proposalIds
    : [];

const rejectedProposalIds =
  review.action === 'reject' ||
  review.action === 'regenerate'
    ? proposalIds
    : [];

return {
  json: {
    application_id: review.application_id,
    idempotency_key: review.review_idempotency_key,
    action: review.action,
    approved_proposal_ids: approvedProposalIds,
    rejected_proposal_ids: rejectedProposalIds,
    edits,
    reviewer_comment: review.reviewer_comment,
  },
};

const structured = $json.structuredContent ?? {};
const submission = structured.submission ?? {};

const status = String(submission.status ?? '').trim().toLowerCase();

const outcome =
  submission.outcome == null
    ? null
    : String(submission.outcome).trim().toLowerCase();

let reviewResultState;

if (
  status === 'completed' &&
  (outcome === 'completed' || outcome === 'awaiting_review')
) {
  reviewResultState = outcome;
} else if (status === 'failed') {
  reviewResultState = 'failed';
} else if (status === 'outcome_unknown') {
  reviewResultState = 'outcome_unknown';
} else {
  throw new Error(
    `Unexpected review result. status=${status || '<blank>'}, outcome=${outcome || '<blank>'}`
  );
}

return {
  json: {
    ...$json,
    review_result_state: reviewResultState,
  },
};

const structured = $json.structuredContent ?? {};
const applicationId =
  structured.application?.application_id ?? '<unknown>';

const state =
  $json.review_result_state ?? '<unknown>';

throw new Error(
  `CareerOps review ended in durable '${state}' state for application ${applicationId}. Manual inspection/recovery is required; the workflow will not guess or retry the business operation.`
);
